import random

from txn_simulator import Workload
from workloads import WORKLOAD_1, WORKLOAD_2, WORKLOAD_3

# EVOLVE-BLOCK-START

def get_best_schedule(workload, num_seqs):
    """
    Conflict-graph DAG critical-path seeding + multi-restart exact-cost
    greedy + hybrid local search (2-opt swaps, or-opt reinsertions,
    segment reversals) + iterated local search with a diverse pool.

    1. Build the transaction conflict graph (edge = shared data key,
       weight = number of shared keys). Compute a criticality score per
       transaction via longest-path relaxation (Graham/Hu-style list
       scheduling priority): transactions on long downstream conflict
       chains are scheduled first.
    2. Construct seeds with a criticality-guided builder: at each step,
       consider the top few remaining transactions by criticality and
       append the one with the lowest TRUE makespan
       (workload.get_opt_seq_cost). Also run plain multi-start greedy.
    3. First-improvement local search with swaps, reinsertions, reversals.
    4. Perturb-and-repolish seeded from a pool of local optima until the
       time budget expires.
    """
    import time

    time_budget = 110.0
    start_time = time.time()
    n = workload.num_txns

    # ---------- conflict graph + critical-path priorities ----------
    def txn_keys(t):
        """Extract the set of data keys of transaction index t."""
        for attr in ("txns", "transactions", "txn_list"):
            data = getattr(workload, attr, None)
            if data is None:
                continue
            item = data[t] if isinstance(data, (list, tuple)) else data.get("txn%d" % t)
            if item is None and isinstance(data, dict):
                for k in (t, str(t), "txn%d" % t):
                    if k in data:
                        item = data[k]
                        break
            if item is None:
                continue
            keys = set()
            if isinstance(item, str):
                toks = item.split()
            elif isinstance(item, (list, tuple)):
                toks = [str(x) for x in item]
            else:
                toks = []
            for tok in toks:
                parts = tok.split("-")
                if len(parts) == 2:
                    keys.add(parts[1])
            if keys or toks:
                return keys
        return set()

    keys_of = {}
    key_map = {}
    for t in range(n):
        ks = txn_keys(t)
        keys_of[t] = ks
        for k in ks:
            key_map.setdefault(k, set()).add(t)

    # adjacency with weights = number of shared keys
    adj = {t: {} for t in range(n)}
    for k, ts in key_map.items():
        ts = sorted(ts)
        for i in range(len(ts)):
            for j in range(i + 1, len(ts)):
                a, b = ts[i], ts[j]
                adj[a][b] = adj[a].get(b, 0) + 1
                adj[b][a] = adj[b].get(a, 0) + 1

    # longest-path criticality: crit[t] = longest weighted path from t
    # to any sink in the (heuristic, undirected-as-DAG) conflict graph.
    crit = {t: 0.0 for t in range(n)}
    for _ in range(n):
        changed = False
        for t in range(n):
            best = 0.0
            for u, w in adj[t].items():
                cand = crit[u] + w
                if cand > best:
                    best = cand
            if best > crit[t]:
                crit[t] = best
                changed = True
        if not changed:
            break
    degree = {t: sum(adj[t].values()) for t in range(n)}

    def critical_path_seed(topk=4):
        """Graham-style list scheduling: repeatedly append the true-cost
        best transaction among the topk most critical remaining ones."""
        remaining = list(range(n))
        seq = []
        while remaining:
            remaining.sort(key=lambda t: (-crit[t], -degree[t], t))
            cands = remaining[:topk]
            best_c, best_t = None, None
            for t in cands:
                c = workload.get_opt_seq_cost(seq + [t])
                if best_c is None or c < best_c:
                    best_c, best_t = c, t
            seq.append(best_t)
            remaining.remove(best_t)
        return workload.get_opt_seq_cost(seq), seq

    def greedy(start_txn, noise=0.0):
        seq = [start_txn]
        remaining = [x for x in range(n) if x != start_txn]
        while remaining:
            scored = []
            for t in remaining:
