            # or-opt: move a single txn to another position
            for i in range(n):
                if time.time() - start_time >= time_budget:
                    return cost, seq
                t = seq.pop(i)
                for j in range(n):
                    if j == i:
                        continue
                    seq.insert(j, t)
                    c = workload.get_opt_seq_cost(seq)
                    if c < cost:
                        cost = c
                        improved = True
                        break
                    seq.pop(j)
                else:
                    seq.insert(i, t)
            # segment reversal: reverse block [i..j]
            for i in range(n - 1):
                for j in range(i + 2, n):
                    if time.time() - start_time >= time_budget:
                        return cost, seq
                    seq[i:j + 1] = seq[i:j + 1][::-1]
                    c = workload.get_opt_seq_cost(seq)
                    if c < cost:
                        cost = c
                        improved = True
                    else:
                        seq[i:j + 1] = seq[i:j + 1][::-1]
        return cost, seq

    best_cost = None
